#include <stdio.h>

struct jogador { int vidas; int pontos; };

void acertar(struct jogador *j, int valor) {
    j->pontos += valor;
    if (j->pontos >= 100) { j->vidas++; j->pontos -= 100; }
}
int main(void) {
    struct jogador p = {3, 80};
    acertar(&p, 30);
    acertar(&p, 50);
    printf("%d %d\n", p.vidas, p.pontos);
    return 0;
}

